contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test accepting an arbitrary amount forwarded to c.play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract can forward the requested amount
        require(address(this).balance >= amount);

        // observe pre-state
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe post-state
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // General invariant: bank never changes; correct-ticket calls do not revert and result
        // in pot either increased by exactly TICKET_AMOUNT or reset to 0; incorrect-ticket
        // calls revert and leave pot and contract balance unchanged.
        // We refer to constants by their numeric values as they are not accessible here.
        assert(
            bankBefore == bankAfter
            && (
                (amount == 10
                    && reverted == false
                    && (potAfter == potBefore + 10 || potAfter == 0)
                )
                || (amount != 10
                    && reverted == true
                    && potAfter == potBefore
                    && balAfter == balBefore
                )
            )
        );
    }

    // allow receiving ETH so transfers to this test contract succeed
    receive() external payable {}
}

